<script setup>
import { computed, onMounted, ref, watch } from 'vue'; import { useRouter, useRoute } from 'vue-router'; import LoginView from './components/LoginView.vue'; import AppSidebar from './components/AppSidebar.vue'; import AppHeader from './components/AppHeader.vue'; import Notifications from './components/ui/Notifications.vue'; import { request } from './lib/http'
const user=ref(null), menu=ref([]), theme=ref(localStorage.getItem('ht-theme')||'light'), notice=ref(''), drawer=ref(false); const router=useRouter(), route=useRoute(); watch(theme,v=>{document.documentElement.dataset.theme=v;localStorage.setItem('ht-theme',v)},{immediate:true}); const title=computed(()=>route.meta.title||'Dashboard')
function notify(message){notice.value=message;setTimeout(()=>notice.value='',3500)} async function loadMenu(){try{menu.value=(await request('/api/navigation')).data}catch(e){notify(e.message)}} async function loggedIn(value){user.value=value;await loadMenu();router.replace({name:'dashboard'})} async function logout(){await request('/logout',{method:'POST'});user.value=null;menu.value=[];router.replace({name:'dashboard'})} function go(name){drawer.value=false;router.push({name})}
onMounted(async()=>{try{const data=await request('/api/bootstrap');if(data.user){user.value=data.user;await loadMenu()}}catch{}})
</script>
<template><Notifications :message="notice"/><LoginView v-if="!user" v-model:theme="theme" @logged-in="loggedIn" @notify="notify"/><div v-else class="admin"><div v-if="drawer" class="backdrop" @click="drawer=false"></div><AppSidebar :items="menu" :active-route="route.name" :open="drawer" @navigate="go" @close="drawer=false"/><div class="app-body"><AppHeader v-model:theme="theme" :user="user" :title="title" @menu="drawer=true" @logout="logout"/><main class="workspace"><router-view @notify="notify"/></main></div></div></template>
